  const degler = () => { const y = GM.durum.oku('isletme-yanit', {}); return X().degerlendirmeler.map(d => ({...d, yanit: y[d.id] ?? d.yanit})); };
  const DEG_TON = {inceleniyor: ['uyari', 'hourglass-half'], yayinda: ['basari', 'circle-check'], reddedildi: ['notr', 'eye-slash']};
  const degRozet = d => GM.durumRozet({metin: X().degDurum[d.durum], ton: DEG_TON[d.durum][0], ikon: DEG_TON[d.durum][1]});
  const fotolar = () => GM.durum.oku('isletme-foto', X().fotograflar);
  const yeniFotolar = [];
  const ozelGunler = () => GM.durum.oku('isletme-ozel', X().ozelGunler).filter(o => o.tarih >= BUGUN()).sort((a, b) => a.tarih.localeCompare(b.tarih));
  const ayarOku = () => ({rezAcik: X().rezAyar.etkin, operasyon: X().mekan.operasyon, ...GM.durum.oku('isletme-ayar', {})});
